"use client";
/* Floppy, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Floppy(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("floppy"); }, []);
  return React.createElement("piix-sprite", { "name": "floppy", ...piixAttrs(props) });
}

export default Floppy;
